    #[arg(short = 'w', long = "workers", default_value = "4", value_name = "WORKERS", help = "Number of parallel workers", long_help = "Number of parallel workers.\n\nDefault is 4; if the value is negative or 0 it uses the number of logical CPUs.\n\n[default: 4]", value_parser = parse_workers)]
