            // If src is dir and final_dest is existing dir, we should error per original logic (Destination Exists for dir)
            // That check will trigger because final_dest exists (as dir) -> error
            let msg = format!("Received error: Destination Exists: Destination file exists and --no-clobber is set., {}", final_dest.display());
