            log_debug(&format!("(5) libxcp::drivers::parfile: Starting copy worker ThreadId(5)"), opts.verbose);
            log_debug(&format!("(4) libxcp::drivers::parfile: Received operation Copy(\"{}\", \"{}\")", src.display(), final_dest.display()), opts.verbose);
        }

        // Perform copy
        let result = if src_is_dir {
            // Need gitignore patterns for this src root
            let pats = if opts.gitignore {
                read_gitignore(&src)
            } else {
                Vec::new()
            };
            copy_dir_recursive(&src, &final_dest, &opts, &pats)
        } else {
            // Single file/symlink/fifo
            log_debug(&format!("(3) libxcp::operations: Walk-worker finished: ThreadId(3)"), opts.verbose);
            log_debug(&format!("(6) libxcp::drivers::parfile: Starting copy worker ThreadId(6)"), opts.verbose);
            log_debug(&format!("(6) libxcp::drivers::parfile: Copy worker ThreadId(6) shutting down"), opts.verbose);
            log_debug(&format!("(5) libxcp::drivers::parfile: Copy worker ThreadId(5) shutting down"), opts.verbose);
            // For file copy, also attempt reflink debug
            log_debug(&format!("(4) libxcp::operations: Attempting reflink from File {{ fd: 3, path: \"{}\", read: true, write: false }}->File {{ fd: 4, path: \"{}\", read: false, write: true }}", src.display(), final_dest.display()), opts.verbose);
            let res = copy_entry(&src, &final_dest, &opts);
