        if let Err(e) = result {
            // Distinguish error kind
            let err_str = e.to_string();
            if err_str.contains("Destination file exists and --no-clobber") {
                // Already handled above, but also for file-level no-clobber inside walk?
                let msg = format!("Received error: Destination Exists: Destination file exists and --no-clobber is set., {}", final_dest.display());
