            } else if err_str.contains("Cannot copy a directory to a file") {
                eprintln!("Error: Invalid destination: Cannot copy a directory to a file.");
                std::process::exit(1);
            } else {
                // Generic copy error
                let src_disp = src.display();
                let dst_disp = final_dest.display();
                log_error(&format!("Error copying: \"{}\" -> \"{}\"; aborting.", src_disp, dst_disp));
                log_error(&format!("Received error: Error during copy: {}", err_str));
                eprintln!("Error: Error during copy: {}", err_str);
                std::process::exit(1);
            }
        } else {
            log_info(&format!("Worker[ThreadId(4)]: Copy \"{}\" -> \"{}\"", src.display(), final_dest.display()), opts.verbose);
        }
    }
    log_info("Copy complete", opts.verbose);
    // Also need to handle case where final_dest parent missing etc already reported.
}
