fn parse_workers(s: &str) -> Result<u32, String> {
    s.parse::<i64>()
        .map_err(|e| e.to_string())
        .and_then(|v| {
            if v < 0 {
                Err("invalid digit found in string".to_string())
            } else {
                Ok(v as u32)
            }
        })
        .or_else(|_| s.parse::<u32>().map_err(|e| e.to_string()))
}
fn parse_block_size(s: &str) -> Result<u64, String> {
    let s_trim = s.trim();
    if s_trim.is_empty() {
        return Err("could not interpret string as byte size".to_string());
    }
    let mut num_end = 0;
    for (i, c) in s_trim.char_indices() {
        if c.is_ascii_digit() || c == '.' {
            num_end = i + c.len_utf8();
        } else {
            break;
        }
    }
    if num_end == 0 {
        return Err("could not interpret string as byte size".to_string());
    }
    let num_str = &s_trim[..num_end];
    let suffix = s_trim[num_end..].trim();
    let val: f64 = num_str.parse().map_err(|_| "could not interpret string as byte size".to_string())?;
    let mult: f64 = if suffix.is_empty() || suffix.eq_ignore_ascii_case("b") {
        1.0
    } else {
        let up = suffix.to_ascii_uppercase();
        match up.as_str() {
            "K" | "KB" => 1000.0,
            "M" | "MB" => 1_000_000.0,
            "G" | "GB" => 1_000_000_000.0,
            "T" | "TB" => 1_000_000_000_000.0,
            "KI" | "KIB" => 1024.0,
            "MI" | "MIB" => 1024.0*1024.0,
            "GI" | "GIB" => 1024.0*1024.0*1024.0,
            "TI" | "TIB" => 1024.0*1024.0*1024.0*1024.0,
            _ => return Err("could not interpret string as byte size".to_string()),
        }
    };
    let bytes = val * mult;
    Ok(bytes as u64)
}
fn parse_reflink(s: &str) -> Result<String, String> {
    match s {
        "auto" | "always" | "never" => Ok(s.to_string()),
        _ => Err(format!("Invalid arguments: Unexpected value for 'reflink': {}", s)),
    }
}
fn parse_backup(s: &str) -> Result<String, String> {
    match s {
        "none" | "off" | "numbered" | "auto" => Ok(s.to_string()),
        _ => Err(format!("Invalid arguments: Unexpected value for 'backup': {}", s)),
    }
}
fn parse_driver(s: &str) -> Result<String, String> {
    match s {
        "parfile" | "parblock" => Ok(s.to_string()),
        _ => Err(format!("Unknown driver: {}", s)),
    }
}

