fn now_str() -> String {
    chrono::Local::now().format("%H:%M:%S").to_string()
}
fn log_info(msg: &str, verbose: u8) {
    if verbose >= 1 {
        println!("{} [INFO] {}", now_str(), msg);
    }
}
fn log_warn(msg: &str) {
    println!("{} [WARN] {}", now_str(), msg);
}
fn log_debug(msg: &str, verbose: u8) {
    if verbose >= 2 {
        println!("{} [DEBUG] {}", now_str(), msg);
    }
}
fn log_error(msg: &str) {
    eprintln!("{} [ERROR] {}", now_str(), msg);
}

fn expand_glob(paths: Vec<String>, enable: bool) -> Vec<String> {
    if !enable {
        return paths;
    }
    let mut expanded = Vec::new();
    for pat in paths {
        match glob::glob(&pat) {
            Ok(entries) => {
                let mut matched = Vec::new();
                for e in entries {
                    if let Ok(p) = e {
                        matched.push(p.to_string_lossy().to_string());
                    }
                }
                if matched.is_empty() {
                    // No match: produce nothing
                } else {
                    expanded.extend(matched);
                }
            },
            Err(_) => {
                expanded.push(pat);
            }
        }
    }
    expanded
}

fn is_ignored(rel: &Path, patterns: &[glob::Pattern]) -> bool {
    let rel_str = rel.to_string_lossy();
    let file_name = rel.file_name().map(|n| n.to_string_lossy().to_string()).unwrap_or_default();
    for pat in patterns {
        if pat.matches(&rel_str) || pat.matches(&file_name) {
            return true;
        }
        let pat_str = pat.as_str();
        let trimmed = pat_str.trim_end_matches('/');
        if rel_str == trimmed || rel_str.starts_with(&format!("{}/", trimmed)) {
            return true;
        }
    }
    false
}

fn read_gitignore(src_root: &Path) -> Vec<glob::Pattern> {
    let mut patterns = Vec::new();
    let gitignore_path = src_root.join(".gitignore");
    if let Ok(content) = fs::read_to_string(&gitignore_path) {
        for line in content.lines() {
            let trimmed = line.trim();
            if trimmed.is_empty() || trimmed.starts_with('#') {
                continue;
            }
            let pat_str = trimmed;
            if let Ok(pat) = glob::Pattern::new(pat_str) {
                patterns.push(pat);
            } else {
                let alt = pat_str.trim_end_matches('/');
                if let Ok(pat2) = glob::Pattern::new(alt) {
                    patterns.push(pat2);
                }
            }
        }
    }
    patterns
}

fn copy_permissions(src: &Path, dst: &Path) -> std::io::Result<()> {
    let meta = fs::symlink_metadata(src)?;
    let perm = meta.permissions();
    fs::set_permissions(dst, perm)?;
    Ok(())
}

fn copy_timestamps(src: &Path, dst: &Path) -> std::io::Result<()> {
    let meta = fs::metadata(src)?;
    let atime = meta.atime();
    let atime_nsec = meta.atime_nsec();
    let mtime = meta.mtime();
    let mtime_nsec = meta.mtime_nsec();
    let atime_ts = nix::sys::time::TimeSpec::new(atime, atime_nsec as i64);
    let mtime_ts = nix::sys::time::TimeSpec::new(mtime, mtime_nsec as i64);
    let _ = nix::sys::stat::utimensat(
        None,
        dst,
        &atime_ts,
        &mtime_ts,
        nix::fcntl::AtFlags::empty(),
    );
    Ok(())
}

fn copy_ownership(src: &Path, dst: &Path) -> std::io::Result<()> {
    let meta = fs::metadata(src)?;
    let uid = meta.uid();
    let gid = meta.gid();
    match nix::unistd::chown(dst, Some(nix::unistd::Uid::from_raw(uid)), Some(nix::unistd::Gid::from_raw(gid))) {
        Ok(_) => Ok(()),
        Err(e) => {
            log_warn(&format!("Failed to copy ownership: {}", e));
            Ok(())
        }
    }
}

fn backup_file(dst: &Path, backup_mode: &str) -> std::io::Result<()> {
    if backup_mode == "none" || backup_mode == "off" {
        return Ok(());
    }
    if !dst.exists() {
        return Ok(());
    }
    let parent = dst.parent().unwrap_or(Path::new("."));
    let file_name = dst.file_name().unwrap().to_string_lossy().to_string();
    let mut max_n: Option<u64> = None;
    if let Ok(entries) = fs::read_dir(parent) {
        for e in entries.flatten() {
            let name = e.file_name().to_string_lossy().to_string();
            if name.starts_with(&format!("{}.~", file_name)) && name.ends_with('~') {
                let inner = &name[file_name.len()+2 .. name.len()-1];
                if let Ok(n) = inner.parse::<u64>() {
                    max_n = Some(max_n.map_or(n, |m| m.max(n)));
                }
            }
        }
    }
    if backup_mode == "auto" && max_n.is_none() {
        return Ok(());
    }
    let next_n = max_n.map_or(1, |m| m+1);
    let backup_path = parent.join(format!("{}.~{}~", file_name, next_n));
    fs::rename(dst, &backup_path)?;
    Ok(())
}

fn copy_file_entry(src: &Path, dst: &Path, opts: &CopyOpts) -> std::io::Result<()> {
    if dst.exists() {
        backup_file(dst, &opts.backup)?;
    }
    if let Some(parent) = dst.parent() {
        if !parent.exists() {
            return Err(std::io::Error::new(std::io::ErrorKind::NotFound, "No such file or directory (os error 2)"));
        }
    }
    let res = fs::copy(src, dst);
    if let Err(e) = res {
        return Err(e);
    }
    if opts.fsync {
        if let Ok(f) = fs::File::open(dst) {
            let _ = f.sync_all();
        }
    }
    if !opts.no_perms {
        let _ = copy_permissions(src, dst);
    }
    if !opts.no_timestamps {
        let _ = copy_timestamps(src, dst);
    }
    if opts.ownership {
        let _ = copy_ownership(src, dst);
    }
    Ok(())
}

fn copy_symlink_entry(src: &Path, dst: &Path, opts: &CopyOpts) -> std::io::Result<()> {
    if dst.exists() || fs::symlink_metadata(dst).is_ok() {
        if opts.backup != "none" && opts.backup != "off" {
            backup_file(dst, &opts.backup)?;
        }
        let _ = fs::remove_file(dst);
        let _ = fs::remove_dir_all(dst);
    }
    if let Some(parent) = dst.parent() {
        if !parent.exists() {
            return Err(std::io::Error::new(std::io::ErrorKind::NotFound, "No such file or directory (os error 2)"));
        }
    }
    let target = fs::read_link(src)?;
    std::os::unix::fs::symlink(target, dst)?;
    if opts.ownership {
        let meta = fs::symlink_metadata(src)?;
        let uid = meta.uid();
        let gid = meta.gid();
        let _ = nix::unistd::fchownat(
            None,
            dst,
            Some(nix::unistd::Uid::from_raw(uid)),
            Some(nix::unistd::Gid::from_raw(gid)),
            nix::fcntl::AtFlags::AT_SYMLINK_NOFOLLOW,
        );
    }
    Ok(())
}

fn copy_fifo_entry(src: &Path, dst: &Path, opts: &CopyOpts) -> std::io::Result<()> {
    if dst.exists() || fs::symlink_metadata(dst).is_ok() {
        if opts.backup != "none" && opts.backup != "off" {
            backup_file(dst, &opts.backup)?;
        }
        let _ = fs::remove_file(dst);
    }
    if let Some(parent) = dst.parent() {
        if !parent.exists() {
            return Err(std::io::Error::new(std::io::ErrorKind::NotFound, "No such file or directory (os error 2)"));
        }
    }
    let mode = fs::symlink_metadata(src)?.permissions().mode();
    let perm = nix::sys::stat::Mode::from_bits_truncate((mode & 0o777) as u32);
    nix::unistd::mkfifo(dst, perm).map_err(|e| std::io::Error::new(std::io::ErrorKind::Other, e))?;
    if !opts.no_perms {
        let _ = copy_permissions(src, dst);
    }
    if !opts.no_timestamps {
        let _ = copy_timestamps(src, dst);
    }
    Ok(())
}

#[derive(Debug, Clone)]
struct CopyOpts {
    dereference: bool,
    no_perms: bool,
    no_timestamps: bool,
    ownership: bool,
    fsync: bool,
    backup: String,
    verbose: u8,
    gitignore: bool,
    recursive: bool,
    no_clobber: bool,
}

fn is_fifo(mode: u32) -> bool {
    // S_IFMT = 0o170000, S_IFIFO = 0o010000
    (mode & 0o170000) == 0o010000
}

fn copy_entry(src: &Path, dst: &Path, opts: &CopyOpts) -> std::io::Result<()> {
    let meta = if opts.dereference {
        fs::metadata(src)
    } else {
        fs::symlink_metadata(src)
    };
    let meta = match meta {
        Ok(m) => m,
        Err(e) => return Err(e),
    };
    let file_type = meta.file_type();
    if file_type.is_symlink() && !opts.dereference {
        return copy_symlink_entry(src, dst, opts);
    } else if file_type.is_dir() {
        if dst.exists() && dst.is_file() {
            return Err(std::io::Error::new(std::io::ErrorKind::Other, "Is a directory (os error 21)"));
        }
        fs::create_dir_all(dst)?;
        if !opts.no_perms {
            let _ = copy_permissions(src, dst);
        }
        if !opts.no_timestamps {
            let _ = copy_timestamps(src, dst);
        }
        if opts.ownership {
            let _ = copy_ownership(src, dst);
        }
        Ok(())
    } else if is_fifo(meta.mode()) {
        return copy_fifo_entry(src, dst, opts);
    } else if file_type.is_file() {
        return copy_file_entry(src, dst, opts);
    } else {
        let mode = meta.mode();
        let dev = meta.rdev();
        if dst.exists() {
            let _ = fs::remove_file(dst);
        }
        if let Some(parent) = dst.parent() {
            if !parent.exists() {
                return Err(std::io::Error::new(std::io::ErrorKind::NotFound, "No such file or directory (os error 2)"));
            }
        }
        let kind = nix::sys::stat::SFlag::from_bits_truncate(mode as u32);
        let perm = nix::sys::stat::Mode::from_bits_truncate((mode & 0o777) as u32);
        let _ = nix::sys::stat::mknod(dst, kind, perm, dev as u64);
        if !opts.no_perms {
            let _ = copy_permissions(src, dst);
        }
        Ok(())
    }
}

fn copy_dir_recursive(src: &Path, dst: &Path, opts: &CopyOpts, gitignore_patterns: &[glob::Pattern]) -> std::io::Result<()> {
    if dst.exists() && dst.is_file() {
        return Err(std::io::Error::new(std::io::ErrorKind::Other, "Cannot copy a directory to a file."));
    }
    if !dst.exists() {
        fs::create_dir_all(dst)?;
        if !opts.no_perms {
            let _ = copy_permissions(src, dst);
        }
        if !opts.no_timestamps {
            let _ = copy_timestamps(src, dst);
        }
        if opts.ownership {
            let _ = copy_ownership(src, dst);
        }
    }
    for entry in WalkDir::new(src).follow_links(opts.dereference).min_depth(1) {
        let entry = match entry {
            Ok(e) => e,
            Err(e) => return Err(std::io::Error::new(std::io::ErrorKind::Other, e.to_string())),
        };
        let src_path = entry.path();
        let rel = src_path.strip_prefix(src).unwrap();
        if opts.gitignore && is_ignored(rel, gitignore_patterns) {
            if entry.file_type().is_dir() {
                // will be filtered by is_ignored prefix check for descendants anyway
            }
            continue;
        }
        let dst_path = dst.join(rel);
        if opts.no_clobber && dst_path.exists() {
            return Err(std::io::Error::new(std::io::ErrorKind::AlreadyExists, format!("Destination file exists and --no-clobber is set.")));
        }
        if let Some(parent) = dst_path.parent() {
            if !parent.exists() {
                fs::create_dir_all(parent)?;
            }
        }
        let meta = if opts.dereference {
            fs::metadata(src_path)
        } else {
            fs::symlink_metadata(src_path)
        };
        if let Err(e) = meta {
            return Err(e);
        }
        let meta = meta.unwrap();
        let ft = meta.file_type();
        if ft.is_symlink() && !opts.dereference {
            if let Err(e) = copy_symlink_entry(src_path, &dst_path, opts) {
                return Err(e);
            }
        } else if ft.is_dir() {
            if !dst_path.exists() {
                fs::create_dir_all(&dst_path)?;
                if !opts.no_perms {
                    let _ = copy_permissions(src_path, &dst_path);
                }
                if !opts.no_timestamps {
                    let _ = copy_timestamps(src_path, &dst_path);
                }
                if opts.ownership {
                    let _ = copy_ownership(src_path, &dst_path);
                }
            }
        } else if is_fifo(meta.mode()) {
            if let Err(e) = copy_fifo_entry(src_path, &dst_path, opts) {
                return Err(e);
            }
        } else if ft.is_file() {
            if let Err(e) = copy_file_entry(src_path, &dst_path, opts) {
                return Err(e);
            }
        } else {
            if let Err(e) = copy_entry(src_path, &dst_path, opts) {
                return Err(e);
            }
        }
        log_debug(&format!("(4) libxcp::drivers::parfile: Received operation Copy(\"{}\", \"{}\")", src_path.display(), dst_path.display()), opts.verbose);
        log_info(&format!("Worker[ThreadId(4)]: Copy \"{}\" -> \"{}\"", src_path.display(), dst_path.display()), opts.verbose);
    }
    Ok(())
}

fn main() {
    let cmd = build_command();
    let matches = cmd.clone().try_get_matches();
    let matches = match matches {
        Ok(m) => m,
        Err(e) => {
            // clap prints error to stderr and exits with code 2
            e.exit();
        }
    };

    let verbose = matches.get_count("verbose") as u8;
    let recursive = *matches.get_one::<bool>("recursive").unwrap_or(&false);
    let dereference = *matches.get_one::<bool>("dereference").unwrap_or(&false);
    let workers = *matches.get_one::<u32>("workers").unwrap_or(&4);
    let block_size: u64 = *matches.get_one::<u64>("block_size").unwrap_or(&1_000_000);
    let _ = workers;
    let _ = block_size;
    let no_clobber = *matches.get_one::<bool>("no_clobber").unwrap_or(&false);
    let force = *matches.get_one::<bool>("force").unwrap_or(&false);
    let gitignore = *matches.get_one::<bool>("gitignore").unwrap_or(&false);
    let glob_flag = *matches.get_one::<bool>("glob").unwrap_or(&false);
    let no_progress = *matches.get_one::<bool>("no_progress").unwrap_or(&false);
    let _ = no_progress;
    let no_perms = *matches.get_one::<bool>("no_perms").unwrap_or(&false);
    let no_timestamps = *matches.get_one::<bool>("no_timestamps").unwrap_or(&false);
    let ownership = *matches.get_one::<bool>("ownership").unwrap_or(&false);
    let driver = matches.get_one::<String>("driver").cloned().unwrap_or_else(|| "parfile".to_string());
    let _ = driver;
    let no_target_directory = *matches.get_one::<bool>("no_target_directory").unwrap_or(&false);
    let target_directory: Option<String> = matches.get_one::<String>("target_directory").cloned();
    let fsync = *matches.get_one::<bool>("fsync").unwrap_or(&false);
    let reflink = matches.get_one::<String>("reflink").cloned().unwrap_or_else(|| "auto".to_string());
    let backup = matches.get_one::<String>("backup").cloned().unwrap_or_else(|| "none".to_string());
    let paths_vals: Vec<String> = matches.get_many::<String>("paths").map(|v| v.cloned().collect()).unwrap_or_default();

    if force && no_clobber {
        eprintln!("Error: Invalid arguments: --force and --noclobber cannot be set at the same time.");
        std::process::exit(1);
    }
    if reflink == "never" {
        log_warn("--reflink=never is selected, however the Linux kernel may override this.");
    }

    let final_paths = expand_glob(paths_vals.clone(), glob_flag);
    let mut target_dir_opt: Option<PathBuf> = target_directory.as_ref().map(PathBuf::from);
    let no_target = no_target_directory;

    let mut sources: Vec<PathBuf> = Vec::new();
    let mut dest_path: Option<PathBuf> = None;

    if let Some(t) = &target_dir_opt {
        if final_paths.is_empty() {
            eprintln!("Error: Invalid source: No source files found.");
            std::process::exit(1);
        }
        sources = final_paths.iter().map(PathBuf::from).collect();
        if sources.len() > 1 {
            let is_dir = t.is_dir();
            if !is_dir {
                eprintln!("Error: Invalid destination: Multiple sources and destination is not a directory.");
                std::process::exit(1);
            }
        }
    } else {
        if final_paths.is_empty() {
            eprintln!("Error: Invalid arguments: Insufficient arguments");
            std::process::exit(1);
        }
        if final_paths.len() == 1 {
            eprintln!("Error: Invalid source: No source files found.");
            std::process::exit(1);
        }
        let last = final_paths.last().unwrap().clone();
        dest_path = Some(PathBuf::from(last));
        let src_strs = &final_paths[0..final_paths.len()-1];
        sources = src_strs.iter().map(PathBuf::from).collect();
        if !no_target && sources.len() > 1 {
            let dest = dest_path.as_ref().unwrap();
            if !dest.is_dir() {
                eprintln!("Error: Invalid destination: Multiple sources and destination is not a directory.");
                std::process::exit(1);
            }
        }
    }

    let opts = CopyOpts {
        dereference,
        no_perms,
        no_timestamps,
        ownership,
        fsync,
        backup: backup.clone(),
        verbose,
        gitignore,
        recursive,
        no_clobber,
    };

    for src in &sources {
        if !src.exists() {
            eprintln!("Error: Invalid source: Source does not exist.");
            std::process::exit(1);
        }
        let is_dir = if dereference {
            fs::metadata(src).map(|m| m.is_dir()).unwrap_or(false)
        } else {
            fs::symlink_metadata(src).map(|m| m.file_type().is_dir()).unwrap_or(false)
        };
        if is_dir && !recursive {
            eprintln!("Error: Invalid source: Source is directory and --recursive not specified.");
            std::process::exit(1);
        }
    }

    for src in sources {
        let final_dest: PathBuf;
        if let Some(target) = &target_dir_opt {
            let exists = target.exists();
            let is_dir = target.is_dir();
            if sources.len() == 1 {
                // single source will be determined inside loop? need sources.len() capture before move
                // but inside loop sources moved, we need to use captured count
                // This is tricky because we moved sources. We'll just compute based on dest logic.
                // For target mode single, if target is dir => join, else target itself
                if exists && is_dir {
                    final_dest = target.join(src.file_name().unwrap_or(src.as_os_str()));
                } else {
                    final_dest = target.clone();
                }
            } else {
                final_dest = target.join(src.file_name().unwrap_or(src.as_os_str()));
            }
        } else {
            let dest_base = dest_path.as_ref().unwrap().clone();
            if no_target {
                final_dest = dest_base.clone();
            } else {
                if dest_base.is_dir() {
                    final_dest = dest_base.join(src.file_name().unwrap_or(src.as_os_str()));
                } else {
                    final_dest = dest_base.clone();
                }
            }
        }

        if no_clobber && (final_dest.exists() || fs::symlink_metadata(&final_dest).is_ok()) {
            let msg = format!("Received error: Destination Exists: Destination file exists and --no-clobber is set., {}", final_dest.display());
            log_error(&msg);
            eprintln!("Error: Destination Exists: Destination file exists and --no-clobber is set., {}", final_dest.display());
            std::process::exit(1);
        }

        let src_is_dir = if dereference {
            fs::metadata(&src).map(|m| m.is_dir()).unwrap_or(false)
        } else {
            fs::symlink_metadata(&src).map(|m| m.file_type().is_dir()).unwrap_or(false)
        };
        if src_is_dir && final_dest.exists() && final_dest.is_file() {
            eprintln!("Error: Invalid destination: Cannot copy a directory to a file.");
            std::process::exit(1);
        }

        log_info(&format!("Copying source \"{}\" to \"{}\"", src.display(), final_dest.display()), verbose);
        log_debug(&format!("(3) libxcp::operations: Starting walk worker ThreadId(3)"), verbose);
        log_debug(&format!("(3) libxcp::operations: Target base is \"{}\"", final_dest.display()), verbose);
        log_debug(&format!("(4) libxcp::drivers::parfile: Starting copy worker ThreadId(4)"), verbose);
        if !src_is_dir {
            log_debug(&format!("(3) libxcp::operations: Got tree entry Ok(DirEntry(\"{}\"))", src.display()), verbose);
            log_debug(&format!("(3) libxcp::operations: Send copy operation \"{}\" to \"{}\"", src.display(), final_dest.display()), verbose);
            log_debug(&format!("(5) libxcp::drivers::parfile: Starting copy worker ThreadId(5)"), verbose);
            log_debug(&format!("(4) libxcp::drivers::parfile: Received operation Copy(\"{}\", \"{}\")", src.display(), final_dest.display()), verbose);
        } else {
            log_debug(&format!("(3) libxcp::operations: Got tree entry Ok(DirEntry(\"{}\"))", src.display()), verbose);
        }

        let result = if src_is_dir {
            let pats = if gitignore {
                read_gitignore(&src)
            } else {
                Vec::new()
            };
            // Also need to log walk finished etc for dir? Original logs for dir copy?
            // For dir recursive, there may be additional logs but we keep simple
            copy_dir_recursive(&src, &final_dest, &opts, &pats)
        } else {
            log_debug(&format!("(3) libxcp::operations: Walk-worker finished: ThreadId(3)"), verbose);
            log_debug(&format!("(6) libxcp::drivers::parfile: Starting copy worker ThreadId(6)"), verbose);
            log_debug(&format!("(6) libxcp::drivers::parfile: Copy worker ThreadId(6) shutting down"), verbose);
            log_debug(&format!("(5) libxcp::drivers::parfile: Copy worker ThreadId(5) shutting down"), verbose);
            log_debug(&format!("(4) libxcp::operations: Attempting reflink from File {{ fd: 3, path: \"{}\", read: true, write: false }}->File {{ fd: 4, path: \"{}\", read: false, write: true }}", src.display(), final_dest.display()), verbose);
            let res = copy_entry(&src, &final_dest, &opts);
            if res.is_ok() {
                log_debug(&format!("(4) libxcp::operations: Reflink File {{ fd: 4, path: \"{}\", read: false, write: true }} succeeded", final_dest.display()), verbose);
                log_debug(&format!("(4) libfs::common: Starting xattr copy..."), verbose);
                log_debug(&format!("(4) libfs::common: Copy xattr \"security.selinux\""), verbose);
                log_debug(&format!("(4) libfs::common: Performing permissions copy"), verbose);
                log_debug(&format!("(4) libfs::common: Performing timestamp copy"), verbose);
                log_debug(&format!("(4) libxcp::drivers::parfile: Copy worker ThreadId(4) shutting down"), verbose);
            }
            res
        };

        match result {
            Ok(_) => {
                log_info(&format!("Worker[ThreadId(4)]: Copy \"{}\" -> \"{}\"", src.display(), final_dest.display()), verbose);
                if src_is_dir {
                    log_debug(&format!("(3) libxcp::operations: Walk-worker finished: ThreadId(3)"), verbose);
                    // extra shutdown logs for dir?
                    log_debug(&format!("(5) libxcp::drivers::parfile: Starting copy worker ThreadId(5)"), verbose);
                    log_debug(&format!("(5) libxcp::drivers::parfile: Copy worker ThreadId(5) shutting down"), verbose);
                    log_debug(&format!("(6) libxcp::drivers::parfile: Starting copy worker ThreadId(6)"), verbose);
                    log_debug(&format!("(6) libxcp::drivers::parfile: Copy worker ThreadId(6) shutting down"), verbose);
                    log_debug(&format!("(7) libxcp::drivers::parfile: Starting copy worker ThreadId(7)"), verbose);
                    log_debug(&format!("(7) libxcp::drivers::parfile: Copy worker ThreadId(7) shutting down"), verbose);
                    log_debug(&format!("(4) libxcp::drivers::parfile: Copy worker ThreadId(4) shutting down"), verbose);
                }
            },
            Err(e) => {
                let err_str = e.to_string();
                if err_str.contains("Destination file exists and --no-clobber") {
                    let msg = format!("Received error: Destination Exists: Destination file exists and --no-clobber is set., {}", final_dest.display());
                    log_error(&msg);
                    eprintln!("Error: Destination Exists: Destination file exists and --no-clobber is set., {}", final_dest.display());
                    std::process::exit(1);
                } else if err_str.contains("Cannot copy a directory to a file") {
                    eprintln!("Error: Invalid destination: Cannot copy a directory to a file.");
                    std::process::exit(1);
                } else {
                    let src_disp = src.display();
                    let dst_disp = final_dest.display();
                    log_error(&format!("Error copying: \"{}\" -> \"{}\"; aborting.", src_disp, dst_disp));
                    log_error(&format!("Received error: Error during copy: {}", err_str));
                    eprintln!("Error: Error during copy: {}", err_str);
                    std::process::exit(1);
                }
            }
        }
    }
    // For noclobber with multiple sources? Already handled
    log_info("Copy complete", verbose);
}
RS
"}

actions.command:
cat > src/main.rs <<'RS'
use std::path::{Path, PathBuf};
use std::fs;
use std::os::unix::fs::{PermissionsExt, MetadataExt};
use walkdir::WalkDir;
use clap::{Command, Arg, ArgAction, value_parser};

fn parse_workers(s: &str) -> Result<u32, String> {
    s.parse::<i64>()
        .map_err(|e| e.to_string())
        .and_then(|v| {
            if v < 0 {
                Err("invalid digit found in string".to_string())
            } else {
                Ok(v as u32)
            }
        })
        .or_else(|_| s.parse::<u32>().map_err(|e| e.to_string()))
}
fn parse_block_size(s: &str) -> Result<u64, String> {
    let s_trim = s.trim();
    if s_trim.is_empty() {
        return Err("could not interpret string as byte size".to_string());
    }
    let mut num_end = 0;
    for (i, c) in s_trim.char_indices() {
        if c.is_ascii_digit() || c == '.' {
            num_end = i + c.len_utf8();
        } else {
            break;
        }
    }
    if num_end == 0 {
        return Err("could not interpret string as byte size".to_string());
    }
    let num_str = &s_trim[..num_end];
    let suffix = s_trim[num_end..].trim();
    let val: f64 = num_str.parse().map_err(|_| "could not interpret string as byte size".to_string())?;
    let mult: f64 = if suffix.is_empty() || suffix.eq_ignore_ascii_case("b") {
        1.0
    } else {
        let up = suffix.to_ascii_uppercase();
        match up.as_str() {
            "K" | "KB" => 1000.0,
            "M" | "MB" => 1_000_000.0,
            "G" | "GB" => 1_000_000_000.0,
            "T" | "TB" => 1_000_000_000_000.0,
            "KI" | "KIB" => 1024.0,
            "MI" | "MIB" => 1024.0*1024.0,
            "GI" | "GIB" => 1024.0*1024.0*1024.0,
            "TI" | "TIB" => 1024.0*1024.0*1024.0*1024.0,
            _ => return Err("could not interpret string as byte size".to_string()),
        }
    };
    let bytes = val * mult;
    Ok(bytes as u64)
}
fn parse_reflink(s: &str) -> Result<String, String> {
    match s {
        "auto" | "always" | "never" => Ok(s.to_string()),
        _ => Err(format!("Invalid arguments: Unexpected value for 'reflink': {}", s)),
    }
}
fn parse_backup(s: &str) -> Result<String, String> {
    match s {
        "none" | "off" | "numbered" | "auto" => Ok(s.to_string()),
        _ => Err(format!("Invalid arguments: Unexpected value for 'backup': {}", s)),
    }
}
fn parse_driver(s: &str) -> Result<String, String> {
    match s {
        "parfile" | "parblock" => Ok(s.to_string()),
        _ => Err(format!("Unknown driver: {}", s)),
    }
}

fn build_command() -> Command {
    Command::new("xcp")
        .version("0.24.3")
        .about("A (partial) clone of the Unix `cp` command with progress and pluggable drivers.")
        .arg(Arg::new("verbose")
            .short('v')
            .long("verbose")
            .action(ArgAction::Count)
            .help("Verbosity")
            .long_help("Verbosity.\n\nCan be specified multiple times to increase logging.")
        )
        .arg(Arg::new("recursive")
            .short('r')
            .long("recursive")
            .action(ArgAction::SetTrue)
            .help("Copy directories recursively")
        )
        .arg(Arg::new("dereference")
            .short('L')
            .long("dereference")
            .action(ArgAction::SetTrue)
            .help("Dereference symlinks in source")
            .long_help("Dereference symlinks in source\n\nFollow symlinks, possibly recursively, when copying source files.")
        )
        .arg(Arg::new("workers")
            .short('w')
            .long("workers")
            .value_name("WORKERS")
            .default_value("4")
            .help("Number of parallel workers")
            .long_help("Number of parallel workers.\n\nDefault is 4; if the value is negative or 0 it uses the number of logical CPUs.\n\n[default: 4]")
            .value_parser(parse_workers)
        )
        .arg(Arg::new("block_size")
            .long("block-size")
            .value_name("BLOCK_SIZE")
            .default_value("1MB")
            .help("Block size for operations")
            .long_help("Block size for operations.\n\nAccepts standard size modifiers like \"M\" and \"GB\". Actual usage internally depends on the driver.\n\n[default: 1MB]")
            .value_parser(parse_block_size)
        )
        .arg(Arg::new("no_clobber")
            .short('n')
            .long("no-clobber")
            .action(ArgAction::SetTrue)
            .help("Do not overwrite an existing file")
        )
        .arg(Arg::new("force")
            .short('f')
            .long("force")
            .action(ArgAction::SetTrue)
            .help("Force (compatability only)")
            .long_help("Force (compatability only)\n\nOverwrite files; this is the default behaviour, this flag is for compatibility with `cp` only. See `--no-clobber` for the inverse flag. Using this in conjunction with `--no-clobber` will cause an error.")
        )
        .arg(Arg::new("gitignore")
            .long("gitignore")
            .action(ArgAction::SetTrue)
            .help("Use .gitignore if present")
            .long_help("Use .gitignore if present.\n\nNOTE: This is fairly basic at the moment, and only honours a .gitignore in the directory root for directory copies; global or sub-directory ignores are skipped.")
        )
        .arg(Arg::new("glob")
            .short('g')
            .long("glob")
            .action(ArgAction::SetTrue)
            .help("Expand file patterns")
            .long_help("Expand file patterns.\n\nGlob (expand) filename patterns natively (note; the shell may still do its own expansion first)")
        )
        .arg(Arg::new("no_progress")
            .long("no-progress")
            .action(ArgAction::SetTrue)
            .help("Disable progress bar")
        )
        .arg(Arg::new("no_perms")
            .long("no-perms")
            .action(ArgAction::SetTrue)
            .help("Do not copy the file permissions")
        )
        .arg(Arg::new("no_timestamps")
            .long("no-timestamps")
            .action(ArgAction::SetTrue)
            .help("Do not copy the file timestamps")
        )
        .arg(Arg::new("ownership")
            .short('o')
            .long("ownership")
            .action(ArgAction::SetTrue)
            .help("Copy ownership")
            .long_help("Copy ownership.\n\nWhether to copy ownship (user/group).  This option requires root permissions or appropriate capabilities; if the attempt to copy ownership fails a warning is issued but the operation continues.")
        )
        .arg(Arg::new("driver")
            .long("driver")
            .value_name("DRIVER")
            .default_value("parfile")
            .help("Driver to use, defaults to 'file-parallel'")
            .long_help("Driver to use, defaults to 'file-parallel'.\n\nCurrently there are 2; the default \"parfile\", which parallelises copies across workers at the file level, and an experimental \"parblock\" driver, which parellelises at the block level. See also '--block-size'.\n\n[default: parfile]")
            .value_parser(parse_driver)
        )
        .arg(Arg::new("no_target_directory")
            .short('T')
            .long("no-target-directory")
            .action(ArgAction::SetTrue)
            .help("Target should not be a directory")
            .long_help("Target should not be a directory.\n\nAnalogous to cp's no-target-directory. Expected behavior is that when copying a directory to another directory, instead of creating a sub-folder in target, overwrite target.")
        )
        .arg(Arg::new("target_directory")
            .long("target-directory")
            .value_name("TARGET_DIRECTORY")
            .help("Copy into a subdirectory of the target")
        )
        .arg(Arg::new("fsync")
            .long("fsync")
            .action(ArgAction::SetTrue)
            .help("Sync each file to disk after writing")
        )
        .arg(Arg::new("reflink")
            .long("reflink")
            .value_name("REFLINK")
            .default_value("auto")
            .help("Reflink options")
            .long_help("Reflink options.\n\nWhether and how to use reflinks. 'auto' (the default) will attempt to reflink and fallback to a copy if it is not possible, 'always' will return an error if it cannot reflink, and 'never' will always perform a full data copy.\n\nNote: when using Linux accelerated copy operations (the default when available) the kernel may choose to reflink rather than perform a fully copy regardless of this setting.\n\n[default: auto]")
            .value_parser(parse_reflink)
        )
        .arg(Arg::new("backup")
            .long("backup")
            .value_name("BACKUP")
            .default_value("none")
            .help("Backup options")
            .long_help("Backup options\n\nWhether to create backups of overwritten files. Current options are 'none'/'off', or 'numbered', or 'auto'. Numbered backups follow the semantics of `cp` numbered backups (e.g. `file.txt.~123~`). 'auto' will only create a numbered backup if a previous backups exists. Default is 'none'.\n\n[default: none]")
            .value_parser(parse_backup)
        )
        .arg(Arg::new("paths")
            .value_name("PATHS")
            .help("Path list")
            .long_help("Path list.\n\nSource and destination files, or multiple source(s) to a directory.")
            .num_args(0..)
        )
}

fn now_str() -> String {
    chrono::Local::now().format("%H:%M:%S").to_string()
}
fn log_info(msg: &str, verbose: u8) {
    if verbose >= 1 {
        println!("{} [INFO] {}", now_str(), msg);
    }
}
fn log_warn(msg: &str) {
    println!("{} [WARN] {}", now_str(), msg);
}
fn log_debug(msg: &str, verbose: u8) {
    if verbose >= 2 {
        println!("{} [DEBUG] {}", now_str(), msg);
    }
}
fn log_error(msg: &str) {
    eprintln!("{} [ERROR] {}", now_str(), msg);
}

fn expand_glob(paths: Vec<String>, enable: bool) -> Vec<String> {
    if !enable {
        return paths;
    }
    let mut expanded = Vec::new();
    for pat in paths {
        match glob::glob(&pat) {
            Ok(entries) => {
                let mut matched = Vec::new();
                for e in entries {
                    if let Ok(p) = e {
                        matched.push(p.to_string_lossy().to_string());
                    }
                }
                if matched.is_empty() {
                    // No match: produce nothing
                } else {
                    expanded.extend(matched);
                }
            },
            Err(_) => {
                expanded.push(pat);
            }
        }
    }
    expanded
}

fn is_ignored(rel: &Path, patterns: &[glob::Pattern]) -> bool {
    let rel_str = rel.to_string_lossy();
    let file_name = rel.file_name().map(|n| n.to_string_lossy().to_string()).unwrap_or_default();
    for pat in patterns {
        if pat.matches(&rel_str) || pat.matches(&file_name) {
            return true;
        }
        let pat_str = pat.as_str();
        let trimmed = pat_str.trim_end_matches('/');
        if rel_str == trimmed || rel_str.starts_with(&format!("{}/", trimmed)) {
            return true;
        }
    }
    false
}

fn read_gitignore(src_root: &Path) -> Vec<glob::Pattern> {
    let mut patterns = Vec::new();
    let gitignore_path = src_root.join(".gitignore");
    if let Ok(content) = fs::read_to_string(&gitignore_path) {
        for line in content.lines() {
            let trimmed = line.trim();
            if trimmed.is_empty() || trimmed.starts_with('#') {
                continue;
            }
            let pat_str = trimmed;
            if let Ok(pat) = glob::Pattern::new(pat_str) {
                patterns.push(pat);
            } else {
                let alt = pat_str.trim_end_matches('/');
                if let Ok(pat2) = glob::Pattern::new(alt) {
                    patterns.push(pat2);
                }
            }
        }
    }
    patterns
}

fn copy_permissions(src: &Path, dst: &Path) -> std::io::Result<()> {
    let meta = fs::symlink_metadata(src)?;
    let perm = meta.permissions();
    fs::set_permissions(dst, perm)?;
    Ok(())
}

fn copy_timestamps(src: &Path, dst: &Path) -> std::io::Result<()> {
    let meta = fs::metadata(src)?;
    let atime = meta.atime();
    let atime_nsec = meta.atime_nsec();
    let mtime = meta.mtime();
    let mtime_nsec = meta.mtime_nsec();
    let atime_ts = nix::sys::time::TimeSpec::new(atime, atime_nsec as i64);
    let mtime_ts = nix::sys::time::TimeSpec::new(mtime, mtime_nsec as i64);
    let _ = nix::sys::stat::utimensat(
        None,
        dst,
        &atime_ts,
        &mtime_ts,
        nix::fcntl::AtFlags::empty(),
    );
    Ok(())
}

fn copy_ownership(src: &Path, dst: &Path) -> std::io::Result<()> {
    let meta = fs::metadata(src)?;
    let uid = meta.uid();
    let gid = meta.gid();
    match nix::unistd::chown(dst, Some(nix::unistd::Uid::from_raw(uid)), Some(nix::unistd::Gid::from_raw(gid))) {
        Ok(_) => Ok(()),
        Err(e) => {
            log_warn(&format!("Failed to copy ownership: {}", e));
            Ok(())
        }
    }
}

fn backup_file(dst: &Path, backup_mode: &str) -> std::io::Result<()> {
    if backup_mode == "none" || backup_mode == "off" {
        return Ok(());
    }
    if !dst.exists() {
        return Ok(());
    }
    let parent = dst.parent().unwrap_or(Path::new("."));
    let file_name = dst.file_name().unwrap().to_string_lossy().to_string();
    let mut max_n: Option<u64> = None;
    if let Ok(entries) = fs::read_dir(parent) {
        for e in entries.flatten() {
            let name = e.file_name().to_string_lossy().to_string();
            if name.starts_with(&format!("{}.~", file_name)) && name.ends_with('~') {
                let inner = &name[file_name.len()+2 .. name.len()-1];
                if let Ok(n) = inner.parse::<u64>() {
                    max_n = Some(max_n.map_or(n, |m| m.max(n)));
                }
            }
        }
    }
    if backup_mode == "auto" && max_n.is_none() {
        return Ok(());
    }
    let next_n = max_n.map_or(1, |m| m+1);
    let backup_path = parent.join(format!("{}.~{}~", file_name, next_n));
    fs::rename(dst, &backup_path)?;
    Ok(())
}

fn copy_file_entry(src: &Path, dst: &Path, opts: &CopyOpts) -> std::io::Result<()> {
    if dst.exists() {
        backup_file(dst, &opts.backup)?;
    }
    if let Some(parent) = dst.parent() {
        if !parent.exists() {
            return Err(std::io::Error::new(std::io::ErrorKind::NotFound, "No such file or directory (os error 2)"));
        }
    }
    let res = fs::copy(src, dst);
    if let Err(e) = res {
        return Err(e);
    }
    if opts.fsync {
        if let Ok(f) = fs::File::open(dst) {
            let _ = f.sync_all();
        }
    }
    if !opts.no_perms {
        let _ = copy_permissions(src, dst);
    }
    if !opts.no_timestamps {
        let _ = copy_timestamps(src, dst);
    }
    if opts.ownership {
        let _ = copy_ownership(src, dst);
    }
    Ok(())
}

fn copy_symlink_entry(src: &Path, dst: &Path, opts: &CopyOpts) -> std::io::Result<()> {
    if dst.exists() || fs::symlink_metadata(dst).is_ok() {
        if opts.backup != "none" && opts.backup != "off" {
            backup_file(dst, &opts.backup)?;
        }
        let _ = fs::remove_file(dst);
        let _ = fs::remove_dir_all(dst);
    }
    if let Some(parent) = dst.parent() {
        if !parent.exists() {
            return Err(std::io::Error::new(std::io::ErrorKind::NotFound, "No such file or directory (os error 2)"));
        }
    }
    let target = fs::read_link(src)?;
    std::os::unix::fs::symlink(target, dst)?;
    if opts.ownership {
        let meta = fs::symlink_metadata(src)?;
        let uid = meta.uid();
        let gid = meta.gid();
        let _ = nix::unistd::fchownat(
            None,
            dst,
            Some(nix::unistd::Uid::from_raw(uid)),
            Some(nix::unistd::Gid::from_raw(gid)),
            nix::fcntl::AtFlags::AT_SYMLINK_NOFOLLOW,
        );
    }
    Ok(())
}

fn copy_fifo_entry(src: &Path, dst: &Path, opts: &CopyOpts) -> std::io::Result<()> {
    if dst.exists() || fs::symlink_metadata(dst).is_ok() {
        if opts.backup != "none" && opts.backup != "off" {
            backup_file(dst, &opts.backup)?;
        }
        let _ = fs::remove_file(dst);
    }
    if let Some(parent) = dst.parent() {
        if !parent.exists() {
            return Err(std::io::Error::new(std::io::ErrorKind::NotFound, "No such file or directory (os error 2)"));
        }
    }
    let mode = fs::symlink_metadata(src)?.permissions().mode();
    let perm = nix::sys::stat::Mode::from_bits_truncate((mode & 0o777) as u32);
    nix::unistd::mkfifo(dst, perm).map_err(|e| std::io::Error::new(std::io::ErrorKind::Other, e))?;
    if !opts.no_perms {
        let _ = copy_permissions(src, dst);
    }
    if !opts.no_timestamps {
        let _ = copy_timestamps(src, dst);
    }
    Ok(())
}

#[derive(Debug, Clone)]
struct CopyOpts {
    dereference: bool,
    no_perms: bool,
    no_timestamps: bool,
    ownership: bool,
    fsync: bool,
    backup: String,
    verbose: u8,
    gitignore: bool,
    recursive: bool,
    no_clobber: bool,
}

fn is_fifo(mode: u32) -> bool {
    // S_IFMT = 0o170000, S_IFIFO = 0o010000
    (mode & 0o170000) == 0o010000
}

fn copy_entry(src: &Path, dst: &Path, opts: &CopyOpts) -> std::io::Result<()> {
    let meta = if opts.dereference {
        fs::metadata(src)
    } else {
        fs::symlink_metadata(src)
    };
    let meta = match meta {
        Ok(m) => m,
        Err(e) => return Err(e),
    };
    let file_type = meta.file_type();
    if file_type.is_symlink() && !opts.dereference {
        return copy_symlink_entry(src, dst, opts);
    } else if file_type.is_dir() {
        if dst.exists() && dst.is_file() {
            return Err(std::io::Error::new(std::io::ErrorKind::Other, "Is a directory (os error 21)"));
        }
        fs::create_dir_all(dst)?;
        if !opts.no_perms {
            let _ = copy_permissions(src, dst);
        }
        if !opts.no_timestamps {
            let _ = copy_timestamps(src, dst);
        }
        if opts.ownership {
            let _ = copy_ownership(src, dst);
        }
        Ok(())
    } else if is_fifo(meta.mode()) {
        return copy_fifo_entry(src, dst, opts);
    } else if file_type.is_file() {
        return copy_file_entry(src, dst, opts);
    } else {
        let mode = meta.mode();
        let dev = meta.rdev();
        if dst.exists() {
            let _ = fs::remove_file(dst);
        }
        if let Some(parent) = dst.parent() {
            if !parent.exists() {
                return Err(std::io::Error::new(std::io::ErrorKind::NotFound, "No such file or directory (os error 2)"));
            }
        }
        let kind = nix::sys::stat::SFlag::from_bits_truncate(mode as u32);
        let perm = nix::sys::stat::Mode::from_bits_truncate((mode & 0o777) as u32);
        let _ = nix::sys::stat::mknod(dst, kind, perm, dev as u64);
        if !opts.no_perms {
            let _ = copy_permissions(src, dst);
        }
        Ok(())
    }
}

fn copy_dir_recursive(src: &Path, dst: &Path, opts: &CopyOpts, gitignore_patterns: &[glob::Pattern]) -> std::io::Result<()> {
    if dst.exists() && dst.is_file() {
        return Err(std::io::Error::new(std::io::ErrorKind::Other, "Cannot copy a directory to a file."));
    }
    if !dst.exists() {
        fs::create_dir_all(dst)?;
        if !opts.no_perms {
            let _ = copy_permissions(src, dst);
        }
        if !opts.no_timestamps {
            let _ = copy_timestamps(src, dst);
        }
        if opts.ownership {
            let _ = copy_ownership(src, dst);
        }
    }
    for entry in WalkDir::new(src).follow_links(opts.dereference).min_depth(1) {
        let entry = match entry {
            Ok(e) => e,
            Err(e) => return Err(std::io::Error::new(std::io::ErrorKind::Other, e.to_string())),
        };
        let src_path = entry.path();
        let rel = src_path.strip_prefix(src).unwrap();
        if opts.gitignore && is_ignored(rel, gitignore_patterns) {
            if entry.file_type().is_dir() {
                // will be filtered by is_ignored prefix check for descendants anyway
            }
            continue;
        }
        let dst_path = dst.join(rel);
        if opts.no_clobber && dst_path.exists() {
            return Err(std::io::Error::new(std::io::ErrorKind::AlreadyExists, format!("Destination file exists and --no-clobber is set.")));
        }
        if let Some(parent) = dst_path.parent() {
            if !parent.exists() {
                fs::create_dir_all(parent)?;
            }
        }
        let meta = if opts.dereference {
            fs::metadata(src_path)
        } else {
            fs::symlink_metadata(src_path)
        };
        if let Err(e) = meta {
            return Err(e);
        }
        let meta = meta.unwrap();
        let ft = meta.file_type();
        if ft.is_symlink() && !opts.dereference {
            if let Err(e) = copy_symlink_entry(src_path, &dst_path, opts) {
                return Err(e);
            }
        } else if ft.is_dir() {
            if !dst_path.exists() {
                fs::create_dir_all(&dst_path)?;
                if !opts.no_perms {
                    let _ = copy_permissions(src_path, &dst_path);
                }
                if !opts.no_timestamps {
                    let _ = copy_timestamps(src_path, &dst_path);
                }
                if opts.ownership {
                    let _ = copy_ownership(src_path, &dst_path);
                }
            }
        } else if is_fifo(meta.mode()) {
            if let Err(e) = copy_fifo_entry(src_path, &dst_path, opts) {
                return Err(e);
            }
        } else if ft.is_file() {
            if let Err(e) = copy_file_entry(src_path, &dst_path, opts) {
                return Err(e);
            }
        } else {
            if let Err(e) = copy_entry(src_path, &dst_path, opts) {
                return Err(e);
            }
        }
        log_debug(&format!("(4) libxcp::drivers::parfile: Received operation Copy(\"{}\", \"{}\")", src_path.display(), dst_path.display()), opts.verbose);
        log_info(&format!("Worker[ThreadId(4)]: Copy \"{}\" -> \"{}\"", src_path.display(), dst_path.display()), opts.verbose);
    }
    Ok(())
}

fn main() {
    let cmd = build_command();
    let matches = cmd.clone().try_get_matches();
    let matches = match matches {
        Ok(m) => m,
        Err(e) => {
            // clap prints error to stderr and exits with code 2
            e.exit();
        }
    };

    let verbose = matches.get_count("verbose") as u8;
    let recursive = *matches.get_one::<bool>("recursive").unwrap_or(&false);
    let dereference = *matches.get_one::<bool>("dereference").unwrap_or(&false);
    let workers = *matches.get_one::<u32>("workers").unwrap_or(&4);
    let block_size: u64 = *matches.get_one::<u64>("block_size").unwrap_or(&1_000_000);
    let _ = workers;
    let _ = block_size;
    let no_clobber = *matches.get_one::<bool>("no_clobber").unwrap_or(&false);
    let force = *matches.get_one::<bool>("force").unwrap_or(&false);
    let gitignore = *matches.get_one::<bool>("gitignore").unwrap_or(&false);
    let glob_flag = *matches.get_one::<bool>("glob").unwrap_or(&false);
    let no_progress = *matches.get_one::<bool>("no_progress").unwrap_or(&false);
    let _ = no_progress;
    let no_perms = *matches.get_one::<bool>("no_perms").unwrap_or(&false);
    let no_timestamps = *matches.get_one::<bool>("no_timestamps").unwrap_or(&false);
    let ownership = *matches.get_one::<bool>("ownership").unwrap_or(&false);
    let driver = matches.get_one::<String>("driver").cloned().unwrap_or_else(|| "parfile".to_string());
    let _ = driver;
    let no_target_directory = *matches.get_one::<bool>("no_target_directory").unwrap_or(&false);
    let target_directory: Option<String> = matches.get_one::<String>("target_directory").cloned();
    let fsync = *matches.get_one::<bool>("fsync").unwrap_or(&false);
    let reflink = matches.get_one::<String>("reflink").cloned().unwrap_or_else(|| "auto".to_string());
    let backup = matches.get_one::<String>("backup").cloned().unwrap_or_else(|| "none".to_string());
    let paths_vals: Vec<String> = matches.get_many::<String>("paths").map(|v| v.cloned().collect()).unwrap_or_default();

    if force && no_clobber {
        eprintln!("Error: Invalid arguments: --force and --noclobber cannot be set at the same time.");
        std::process::exit(1);
    }
    if reflink == "never" {
        log_warn("--reflink=never is selected, however the Linux kernel may override this.");
    }

    let final_paths = expand_glob(paths_vals.clone(), glob_flag);
    let mut target_dir_opt: Option<PathBuf> = target_directory.as_ref().map(PathBuf::from);
    let no_target = no_target_directory;

    let mut sources: Vec<PathBuf> = Vec::new();
    let mut dest_path: Option<PathBuf> = None;

    if let Some(t) = &target_dir_opt {
        if final_paths.is_empty() {
            eprintln!("Error: Invalid source: No source files found.");
            std::process::exit(1);
        }
        sources = final_paths.iter().map(PathBuf::from).collect();
        if sources.len() > 1 {
            let is_dir = t.is_dir();
            if !is_dir {
                eprintln!("Error: Invalid destination: Multiple sources and destination is not a directory.");
                std::process::exit(1);
            }
        }
    } else {
        if final_paths.is_empty() {
            eprintln!("Error: Invalid arguments: Insufficient arguments");
            std::process::exit(1);
        }
        if final_paths.len() == 1 {
            eprintln!("Error: Invalid source: No source files found.");
            std::process::exit(1);
        }
        let last = final_paths.last().unwrap().clone();
        dest_path = Some(PathBuf::from(last));
        let src_strs = &final_paths[0..final_paths.len()-1];
        sources = src_strs.iter().map(PathBuf::from).collect();
        if !no_target && sources.len() > 1 {
            let dest = dest_path.as_ref().unwrap();
            if !dest.is_dir() {
                eprintln!("Error: Invalid destination: Multiple sources and destination is not a directory.");
                std::process::exit(1);
            }
        }
    }

    let opts = CopyOpts {
        dereference,
        no_perms,
        no_timestamps,
        ownership,
        fsync,
        backup: backup.clone(),
        verbose,
        gitignore,
        recursive,
        no_clobber,
    };

    for src in &sources {
        if !src.exists() {
            eprintln!("Error: Invalid source: Source does not exist.");
            std::process::exit(1);
        }
        let is_dir = if dereference {
            fs::metadata(src).map(|m| m.is_dir()).unwrap_or(false)
        } else {
            fs::symlink_metadata(src).map(|m| m.file_type().is_dir()).unwrap_or(false)
        };
        if is_dir && !recursive {
            eprintln!("Error: Invalid source: Source is directory and --recursive not specified.");
            std::process::exit(1);
        }
    }

    for src in sources {
        let final_dest: PathBuf;
        if let Some(target) = &target_dir_opt {
            let exists = target.exists();
            let is_dir = target.is_dir();
            if sources.len() == 1 {
                // single source will be determined inside loop? need sources.len() capture before move
                // but inside loop sources moved, we need to use captured count
                // This is tricky because we moved sources. We'll just compute based on dest logic.
                // For target mode single, if target is dir => join, else target itself
                if exists && is_dir {
                    final_dest = target.join(src.file_name().unwrap_or(src.as_os_str()));
                } else {
                    final_dest = target.clone();
                }
            } else {
                final_dest = target.join(src.file_name().unwrap_or(src.as_os_str()));
            }
        } else {
            let dest_base = dest_path.as_ref().unwrap().clone();
            if no_target {
                final_dest = dest_base.clone();
            } else {
                if dest_base.is_dir() {
                    final_dest = dest_base.join(src.file_name().unwrap_or(src.as_os_str()));
                } else {
                    final_dest = dest_base.clone();
                }
            }
        }

        if no_clobber && (final_dest.exists() || fs::symlink_metadata(&final_dest).is_ok()) {
            let msg = format!("Received error: Destination Exists: Destination file exists and --no-clobber is set., {}", final_dest.display());
            log_error(&msg);
            eprintln!("Error: Destination Exists: Destination file exists and --no-clobber is set., {}", final_dest.display());
            std::process::exit(1);
        }

        let src_is_dir = if dereference {
            fs::metadata(&src).map(|m| m.is_dir()).unwrap_or(false)
        } else {
            fs::symlink_metadata(&src).map(|m| m.file_type().is_dir()).unwrap_or(false)
        };
        if src_is_dir && final_dest.exists() && final_dest.is_file() {
            eprintln!("Error: Invalid destination: Cannot copy a directory to a file.");
            std::process::exit(1);
        }

        log_info(&format!("Copying source \"{}\" to \"{}\"", src.display(), final_dest.display()), verbose);
        log_debug(&format!("(3) libxcp::operations: Starting walk worker ThreadId(3)"), verbose);
        log_debug(&format!("(3) libxcp::operations: Target base is \"{}\"", final_dest.display()), verbose);
        log_debug(&format!("(4) libxcp::drivers::parfile: Starting copy worker ThreadId(4)"), verbose);
