            log_debug(&format!("(5) libxcp::drivers::parfile: Starting copy worker ThreadId(5)"), verbose);
            log_debug(&format!("(4) libxcp::drivers::parfile: Received operation Copy(\"{}\", \"{}\")", src.display(), final_dest.display()), verbose);
        } else {
            log_debug(&format!("(3) libxcp::operations: Got tree entry Ok(DirEntry(\"{}\"))", src.display()), verbose);
        }

        let result = if src_is_dir {
            let pats = if gitignore {
                read_gitignore(&src)
            } else {
