                    log_error(&format!("Received error: Error during copy: {}", err_str));
                    eprintln!("Error: Error during copy: {}", err_str);
                    std::process::exit(1);
                }
            }
        }
    }
    // For noclobber with multiple sources? Already handled
    log_info("Copy complete", verbose);
